Q: Javascript Add Event Listener for change in Audio Volume A: <p>Use event volumechange. How to create audio that remembers the volume:</p>
<pre><code>const audio = document.createElement('audio');
audio.setAttribute('controls', '');

audio.volume = localStorage.getItem('audio_volume') || 0.5;
audio.addEventListener('volumechange', function(e) {
    localStorage.setItem('audio_volume', audio.volume);
}, false);

const source = document.createElement('source');
source.src = 'https://download.samplelib.com/mp3/sample-12s.mp3';
audio.appendChild(source);
document.appendChild(audio);
</code></pre>

Q: How to check if a function is a constructor A: <p>If speed is what you're after and you're not worried about edge cases:</p>
<pre><code>typeof value=='function' &amp;&amp; !!value.prototype
</code></pre>
<p>But these days there are better ways, like this cross-browser solution that also works with bound functions. Works in both modern and ES3+ browsers / nodejs:</p>
<pre><code>var isConstructor = typeof Proxy=='function'?
function(value) {// Works in modern environments that support Proxy (ES6+)
    if (typeof value=='function') {
        try {// Throws if `value` is not a constructor function
            var success = new new Proxy(value, {construct:Object});
        }
        catch(e) {
        }
    }
    return !!success
}:
function(value) {// Tested in pre-ES6 JS including Internet Explorer 6 and up
    // Object.prototype.toString() is better than `typeof` pre-ES6
    // since it rules out generators and typeof returns unexpected results
    var is_function = {}.toString.call(value)=='[object Function]';

    // If prototype property in function, it is probably a constructor
    // Except IE where !!alert.prototype//true for host functions
    var has_proto_prop = is_function &amp;&amp; 'prototype' in value;

    // If function has a prototype property and is not a built-in
    // beginning with lowercase, it is probably a construtor.
    var success = has_proto_prop &amp;&amp; !/^\s*\w+ [a-z_]\w*\(\) {\s*\[native c/.test(value);

    // In IE, value could be a constructor where typeof value=='object'
    // Or no prototype property means value might be a bound function
    if (typeof value=='object' || is_function &amp;&amp; !has_proto_prop) {
        try {
            // instanceof throws when no prototype property in bound target
            // Doesn't throw if value is constructor where typeof value=='object'
            success = {} instanceof value || true
        }
        catch(e) {
        }
    }
    return success
}
isConstructor(window)//false
isConstructor(alert)//false
isConstructor(XMLHttpRequest)//true
isConstructor(Array.bind())//true
isConstructor(function myFunc(){})//true
isConstructor(function* myGenerator(){})//false
// Caveat: IE returns false-positives on bound host objects
isConstructor(alert.bind())//false (true in IE / false positive with bound host object)
isConstructor(isNaN.bind())//false (still false in IE / not a host object)
</code></pre>
<p>Here's best of both worlds. This prioritizes speed over edge cases while still supporting bound functions in ES6+ environments:</p>
<pre><code>function isConstructorFast(value) {
    if (typeof value=='function') {
        if (value.prototype) {
            var success = true;
        }
        else if (/^bound /.test(value.name)) {
            try {
                success = new new Proxy(value, {construct:Object});
            }
            catch(e) {
            }
        }
    }
    return !!success;
}
</code></pre>

Q: Accessing the individual words of the content a file A: <p>To be honest there are multiple ways of doing this, from top of my head you can load the entire file from memory and just split it then into individual words as strings.</p>
<pre class="lang-golang prettyprint-override"><code>file, err := os.ReadFile(&quot;sample.txt&quot;)
if err != nil {
    fmt.Println(&quot;An error occurred when trying to read the file&quot;)
    return
}

text := string(file)
words := strings.Fields(text)

for _, word := range words {
    fmt.Println(word)
}
</code></pre>
<p>Or you could buffer and chunk everything like how the other commenter said</p>
<pre class="lang-golang prettyprint-override"><code>file, err := os.Open(&quot;sample.txt&quot;)
if err != nil {
    fmt.Println(&quot;Error opening file&quot;)
    return
}
defer file.Close()

scanner := bufio.NewScanner(file)
scanner.Split(bufio.ScanWords)

for scanner.Scan() {
    fmt.Println(scanner.Text())
}
</code></pre>
